import {forecast,features,predict,parseCSV} from './engine.js';
const $=s=>document.querySelector(s);const main=$('#main');
let model,benchmark,people;let selected=0,view='overview',horizon=120,timer=null,withheld=false,stale=false,threshold=180;
const clock=m=>`${String(Math.floor(((m%1440)+1440)%1440/60)).padStart(2,'0')}:${String(Math.round(m%60)).padStart(2,'0')}`;
const num=(x,n=0)=>Number(x).toFixed(n);const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function download(name,text,type='application/json'){const a=document.createElement('a');const u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
const button=(label,id,primary=false)=>`<button class="button ${primary?'primary':''}" id="${id}">${label}</button>`;
function heading(eyebrow,title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function p(){return people[selected];}
function result(){let person=p();const c=person.cursor;if(withheld){person=structuredClone(person);person.readings[c-2].glucose=null;}return forecast(model,person,c,person.readings[c].minute+(stale?25:0));}
function sidebar(){const el=$('#patients');el.innerHTML=people.map((person,i)=>`<button class="patient ${selected===i?'active':''}" data-person="${i}"><span class="person-icon">${['AN','RV','MR'][i]}</span><span><strong>${escape(person.profile.name)}</strong><small>${person.profile.id} · Type 2 diabetes</small></span><span class="tiny-dot"></span></button>`).join('');el.querySelectorAll('button').forEach(b=>b.onclick=()=>{stop();selected=Number(b.dataset.person);withheld=stale=false;render();});document.querySelectorAll('.nav').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.onclick=()=>{stop();view=b.dataset.view;render();};});}
function stop(){clearInterval(timer);timer=null;}
function render(){sidebar();$('#pageTitle').textContent={overview:'Patient overview',evidence:'Model & evidence',data:'Data studio'}[view];main.innerHTML=`<div class="appear">${view==='overview'?overview():view==='evidence'?evidence():dataStudio()}</div>`;if(view==='overview')bindOverview();if(view==='data')bindData();if(view==='evidence')$('#exportMetrics').onclick=()=>download('glyra-benchmark.json',JSON.stringify(benchmark,null,2));}
function overview(){const person=p(),pr=person.profile,c=person.cursor,r=result(),now=person.readings[c];const last=r.points.at(-1);const crossing=r.points.find(pt=>pt.value>=threshold);const peak=Math.max(...r.points.map(pt=>pt.value));
return `${heading('A CLEARER VIEW OF WHAT COMES NEXT','A little context. A better forecast.','One patient, two data streams, and a transparent view of the next two hours.',button('↗ &nbsp; Export review','exportReview'))}
<section class="person-header" aria-label="Selected patient"><span class="person-icon">${['AN','RV','MR'][selected]}</span><div><strong>${escape(pr.name)}</strong><small>${pr.id} &nbsp;·&nbsp; ${pr.age} years &nbsp;·&nbsp; Type 2 diabetes</small></div><div class="person-meta"><div><span class="meta-label">RECORD SOURCE</span><span class="meta-value">Synthetic EHR</span></div><div><span class="meta-label">SESSION</span><span class="meta-value">Day ${Math.floor(now.minute/1440)+1}, ${clock(now.minute)}</span></div><div><span class="meta-label">TWIN STATUS</span><span class="chip ${r.quality.ok?'':'warning'}">● &nbsp;${r.quality.ok?'Ready to review':'Forecast withheld'}</span></div></div></section>
<section class="stats" aria-label="Forecast summary"><article class="stat"><div class="stat-label">Current glucose <span>◉</span></div><div class="stat-number">${num(now.glucose)}<small>mg/dL</small></div><div class="stat-caption green">Updated ${clock(now.minute)} · simulated CGM</div></article><article class="stat"><div class="stat-label">Forecast at +120 min <span>↗</span></div><div class="stat-number">${last?num(last.value):'—'}<small>mg/dL</small></div><div class="stat-caption">${last?`${num(last.value-last.halfWidth)}–${num(last.value+last.halfWidth)} mg/dL · calibrated interval`:'A complete data window is required'}</div></article><article class="stat"><div class="stat-label">Expected peak in window <span>⌁</span></div><div class="stat-number">${r.quality.ok?num(peak):'—'}<small>mg/dL</small></div><div class="stat-caption">Four forecast horizons · 30 to 120 minutes</div></article><article class="stat highlight"><div class="stat-label">Review threshold <span>◷</span></div><div class="stat-number">${r.quality.ok?(crossing?'+'+crossing.horizon:'—'):'—'}<small>${crossing?'min':'crossing'}</small></div><div class="stat-caption">${r.quality.ok?(crossing?`First point above ${threshold} mg/dL`:`No point forecast above ${threshold} mg/dL`):'Withheld until data quality recovers'}</div></article></section>
<div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Glucose trajectory</h2><div class="panel-sub">Recent readings and a forecast that carries its uncertainty</div></div><div class="segmented" aria-label="Forecast horizon">${[60,120].map(h=>`<button data-horizon="${h}" class="${horizon===h?'active':''}">${h===60?'1 hour':'2 hours'}</button>`).join('')}</div></div><div class="legend"><span><i></i>Observed</span><span><i class="dash"></i>Forecast</span><span><i class="band"></i>90% nominal interval</span><span><i class="threshold"></i>Review threshold</span></div><div class="chart-wrap">${r.quality.ok?chart(person,r.points):`<div class="empty"><strong>Forecast withheld</strong><span>${escape(r.quality.reasons.join(' '))}</span></div>`}</div><div class="timeline-controls"><button id="play" ${person.imported?'disabled':''} aria-label="${timer?'Pause':'Play'} synthetic data replay">${timer?'Ⅱ':'▶'}</button><time>${clock(now.minute)}</time><input aria-label="Replay timeline" type="range" id="timeline" min="12" max="${person.imported?person.readings.length-1:person.readings.length-25}" value="${c}"><span class="subtle" style="font-size:9px">Replay</span></div><div class="insight"><span>✧</span><div><strong>${r.quality.ok?'Known history, visible uncertainty.':'Reliable input comes first.'}</strong><br>${r.quality.ok?'The forecast combines recent CGM, logged meals, and the health record. Unlogged future events can change the outcome.':escape(r.quality.reasons[0])}</div></div></section>
<div class="stack"><section class="panel"><div class="panel-head"><h2>Patient context</h2><span class="source-line">● EHR</span></div><div class="context-body"><dl><div><dt>HbA1c</dt><dd>${num(pr.a1c,1)}%</dd></div><div><dt>Fasting baseline</dt><dd>${num(pr.fasting)} mg/dL</dd></div><div><dt>Previous night’s sleep</dt><dd>${num(pr.sleep,1)} hours</dd></div><div><dt>Activity index</dt><dd>${num(pr.activity,2)} / 1</dd></div></dl>${button('⌘ &nbsp; Explore a scenario','scenario')}</div><div class="context-note">Context shapes the model’s forecast. Scenario changes are exploratory and do not predict treatment effects.</div></section></div></div>
<div class="bottom-grid"><section class="panel"><div class="panel-head"><div><h2>Recent events</h2><div class="panel-sub">Only events logged before the replay time reach the model</div></div><button class="link-button" id="allData">View source data ↗</button></div><div class="event-list">${events(person).map(m=>`<div class="event"><span class="event-icon">${m.carbs?'◌':'≋'}</span><div><strong>${escape(m.label)}</strong><small>${m.carbs?`${m.carbs} g carbohydrate · synthetic meal log`:'Five-minute cadence · synthetic sensor'}</small></div><time>${clock(m.minute)}</time></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Data quality</h2><span class="chip ${r.quality.ok?'':'warning'}">${r.quality.ok?'Passed':'Needs review'}</span></div><div class="quality"><div class="quality-row"><span>Recent readings</span><span>${r.quality.ok?'13 / 13':'Check required'}</span></div><div class="progress-track"><div style="width:${r.quality.ok?100:60}%"></div></div><div class="quality-row"><span>Latest reading age</span><span>${stale?'25 min':'0 min'}</span></div><div class="quality-row"><span>Inference</span><span>On this device</span></div>${button('Inspect quality checks','qualityInfo')}</div></section></div><div class="notice">Synthetic research demonstration. The interval is calibrated on a separate simulated cohort and is pointwise; it has no guaranteed coverage for real patients or edited scenarios. The ${threshold} mg/dL review threshold is illustrative. Glyra gives no diagnosis, medication, or dosing advice.</div>`;}
function chart(person,points){const c=person.cursor;const history=person.readings.slice(Math.max(0,c-48),c+1),now=history.at(-1);const pts=points.filter(v=>v.horizon<=horizon);const W=780,H=274,L=44,R=22,T=30,B=38;const start=now.minute-240,end=now.minute+horizon;const min=60,max=320;const x=t=>L+(t-start)/(end-start)*(W-L-R);const y=g=>T+(max-g)/(max-min)*(H-T-B);const line=a=>a.map((v,i)=>`${i?'L':'M'}${x(v.minute).toFixed(1)},${y(v.glucose).toFixed(1)}`).join(' ');const fs=[{minute:now.minute,glucose:now.glucose},...pts.map(v=>({minute:now.minute+v.horizon,glucose:v.value}))];const upper=[{minute:now.minute,glucose:now.glucose},...pts.map(v=>({minute:now.minute+v.horizon,glucose:v.value+v.halfWidth}))];const lower=[{minute:now.minute,glucose:now.glucose},...pts.map(v=>({minute:now.minute+v.horizon,glucose:v.value-v.halfWidth}))].reverse();
 return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Glucose over the last four hours, followed by a ${horizon}-minute forecast with an uncertainty band. Current ${num(now.glucose)}, next two hours ${points.map(v=>num(v.value)).join(', ')} mg/dL."><defs><clipPath id="plot"><rect x="${L}" y="${T}" width="${W-L-R}" height="${H-T-B}"/></clipPath></defs>${[80,140,200,260,320].map(g=>`<path class="grid" d="M${L},${y(g)}H${W-R}"/><text x="${L-10}" y="${y(g)+3}" text-anchor="end">${g}</text>`).join('')}<text x="${L}" y="15">mg/dL</text><g clip-path="url(#plot)"><path class="band" d="${line(upper)} ${line(lower).replace('M','L')}Z"/><path class="threshold" d="M${L},${y(threshold)}H${W-R}"/><path class="baseline" d="M${x(now.minute)},${y(now.glucose)}H${W-R}"/><path class="history" d="${line(history)}"/><path class="prediction" d="${line(fs)}"/><path class="now" d="M${x(now.minute)},${T}V${H-B}"/><circle cx="${x(now.minute)}" cy="${y(now.glucose)}" r="5"/>${pts.map(v=>`<circle cx="${x(now.minute+v.horizon)}" cy="${y(v.value)}" r="3.7"><title>+${v.horizon} min: ${num(v.value)} mg/dL; interval ${num(v.value-v.halfWidth)} to ${num(v.value+v.halfWidth)}</title></circle>`).join('')}</g><text x="${x(now.minute)}" y="18" text-anchor="middle">NOW</text>${[-240,-180,-120,-60,0,60,120].filter(h=>h<=horizon).map(h=>`<text x="${x(now.minute+h)}" y="${H-12}" text-anchor="middle">${h===0?'Now':h>0?'+'+h+'m':clock(now.minute+h)}</text>`).join('')}</svg>`;
}
function events(person){const t=person.readings[person.cursor].minute;return [{minute:t,label:'CGM stream synced'},...person.meals.filter(m=>m.minute<=t).sort((a,b)=>b.minute-a.minute).slice(0,2)];}
function bindOverview(){document.querySelectorAll('[data-horizon]').forEach(b=>b.onclick=()=>{horizon=Number(b.dataset.horizon);render();});$('#timeline').oninput=e=>{p().cursor=Number(e.target.value);render();};$('#play').onclick=()=>{if(timer){stop();render();return;}timer=setInterval(()=>{p().cursor=Math.min(p().cursor+1,p().readings.length-25);if(p().cursor===p().readings.length-25)stop();render();},900);render();};$('#allData').onclick=()=>{stop();view='data';render();};$('#scenario').onclick=scenario;$('#exportReview').onclick=()=>{const person=p();download('glyra-review.json',JSON.stringify({model:model.version,synthetic:true,profile:person.profile,minute:person.readings[person.cursor].minute,forecast:result(),threshold,limitations:benchmark.limits,aiAssistance:'Codex assisted implementation and documentation.'},null,2));toast('Review exported with provenance and limitations.');};$('#qualityInfo').onclick=()=>{modal(`<h2>Data-quality gates</h2><p>Glyra checks the recent window before running the model. Failed checks withhold all forecast points.</p><ol><li>At least 13 ordered readings</li><li>Approximately five-minute spacing</li><li>Latest reading within 10 minutes</li><li>Finite glucose values inside 40–400 mg/dL</li><li>Health record within the generator’s supported ranges</li></ol><p>These gates check input compatibility. They do not establish clinical safety.</p><div class="data-actions">${button(withheld?'Restore readings':'Simulate a missing reading','missing')}${button(stale?'Restore freshness':'Simulate stale data','stale')}</div>`);$('#missing').onclick=()=>{withheld=!withheld;$('#modal').close();render();};$('#stale').onclick=()=>{stale=!stale;$('#modal').close();render();};};}
function modal(html){$('#modalBody').innerHTML=html;$('#modal').showModal();}
$('#modal .close').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').close();};
function scenario(){const original=p().profile;modal(`<div class="eyebrow">EXPLORATORY SCENARIO</div><h2>What changes with context?</h2><p>Change a synthetic record input to inspect model sensitivity while keeping CGM history fixed. This is a model comparison, with no causal or treatment interpretation.</p><label>Previous night’s sleep: <strong id="sleepValue">${original.sleep}</strong> hours<input id="sleep" type="range" min="4.5" max="8.5" step="0.5" value="${original.sleep}"></label><label>Activity index: <strong id="activityValue">${original.activity}</strong><input id="activity" type="range" min="0" max="0.9" step="0.01" value="${original.activity}"></label><div class="screen-note" id="scenarioResult"></div><p>Uncertainty bands calibrated on the original simulated cohort do not guarantee coverage for this edited scenario.</p>${button('Close scenario','closeScenario',true)}`);const update=()=>{const cp=structuredClone(p());cp.profile.sleep=Number($('#sleep').value);cp.profile.activity=Number($('#activity').value);$('#sleepValue').textContent=num(cp.profile.sleep,1);$('#activityValue').textContent=num(cp.profile.activity,2);const a=forecast(model,p(),p().cursor).points.at(-1);const b=forecast(model,cp,cp.cursor).points.at(-1);$('#scenarioResult').textContent=a&&b?`Forecast at +120 minutes: ${num(a.value)} mg/dL with the original record; ${num(b.value)} mg/dL with the edited record. Difference: ${num(b.value-a.value,1)} mg/dL.`:'The data-quality gate must pass before comparing scenarios.';};$('#sleep').oninput=update;$('#activity').oninput=update;$('#closeScenario').onclick=()=>$('#modal').close();update();}
function evidence(){return `${heading('TRANSPARENCY BY DESIGN','Every forecast has a paper trail.','Reproducible training, a held-out benchmark, and limitations you can inspect.',button('↓ &nbsp; Benchmark JSON','exportMetrics'))}<div class="screen-note">All benchmark results below come from generated data. They describe this simulator only and do not establish accuracy, safety, or usefulness for real patients.</div><section class="panel"><div class="panel-head"><div><h2>Held-out synthetic benchmark</h2><div class="panel-sub">25 unseen synthetic people · ${benchmark.testWindows.toLocaleString()} forecast windows · units mg/dL</div></div><span class="chip">Patient-disjoint split</span></div><div class="table-wrap"><table><thead><tr><th>Horizon</th><th>Glyra MAE</th><th>Persistence MAE</th><th>RMSE</th><th>Interval coverage</th></tr></thead><tbody>${benchmark.metrics.map(m=>`<tr><td>+${m.horizon} min</td><td><strong>${m.mae}</strong></td><td>${m.persistenceMAE}</td><td>${m.rmse}</td><td>${m.coverage}%</td></tr>`).join('')}</tbody></table></div></section><div class="evidence-grid" style="margin-top:20px"><section class="panel"><div class="panel-head"><h2>How the twin works</h2></div><div class="prose"><div class="flow"><div><strong>01 · Two synchronized streams</strong>Synthetic EHR supplies fasting baseline, HbA1c, age, sleep and activity. Five-minute CGM and logged meals supply recent dynamics.</div><div><strong>02 · An input gate</strong>Ordered, fresh, complete data inside the supported ranges pass to inference. A missing window withholds the forecast.</div><div><strong>03 · Four learned forecasts</strong>Ridge regression predicts at 30, 60, 90 and 120 minutes. Normalization uses training people only. Future meals never enter the features.</div><div><strong>04 · Separate interval calibration</strong>Absolute residuals on calibration people set a nominal 90% pointwise interval. A separate test group supplies the displayed empirical coverage.</div></div></div></section><section class="panel"><div class="panel-head"><h2>Model card</h2></div><div class="prose"><h3>Data & splits</h3><p>150 synthetic people; 100 training, 25 calibration, 25 testing. Four days per person. Generator seed: 4100 + person ID. Train.py creates all fixtures and results.</p><h3>Limitations</h3><p>Unannounced meals can cause large errors. Synthetic dynamics simplify human physiology. Windows within each person are dependent. Calibration does not guarantee coverage for real patients, trajectories, or edited records.</p><h3>Clinical boundary</h3><p>No real patient validation, diagnosis or medication advice. Real-world work needs independent retrospective evaluation and clinician oversight.</p></div></section></div><section class="panel" style="margin-top:20px"><div class="prose"><h3>Research & attribution</h3><p><a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC6806292/" target="_blank" rel="noreferrer">Long-term glucose forecasting with a physiological model</a> motivates investigating meal history and highlights difficult long horizons. Its type 1 findings do not validate this type 2 demonstration.</p><p><a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC11373455/" target="_blank" rel="noreferrer">Neural Physiological Model</a> explores glucose and daily-event data. <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC13119999/" target="_blank" rel="noreferrer">Temporal and Behaviour-Aware Modelling</a> describes participant-level splits.</p><p>MIT-licensed source. Codex assisted code, design, research, documentation and submission preparation. Sanjay P · Chennai Institute of Technology · AI & ML · 2029.</p></div></section>`;}
function dataStudio(){const person=p(),c=person.cursor;return `${heading('TWO STREAMS. EXPLICIT PROVENANCE.','A workspace you can inspect.','Import a synthetic five-minute series or explore the included fixtures.')}<div class="screen-note">Use synthetic or appropriately anonymized data only. Imports stay in browser memory and disappear on reload. Imported readings pair with the current demo EHR; no meal events are inferred. Results from unmatched real physiology are unsupported.</div><section class="panel"><div class="prose"><h3>Local CSV import</h3><p>Two columns: <code>minute,glucose</code>. Provide at least 13 ordered readings, exactly five minutes apart. Supported glucose range: 40–400 mg/dL. Limit: 5,000 rows.</p><div class="data-actions"><label class="button primary file-label">↑ Import synthetic CSV<input type="file" id="import" accept=".csv,text/csv"></label>${button('↓ Download current CSV','downloadCSV')}${button('Restore demo fixtures','restore')}</div><p id="importStatus" role="status">Current source: ${person.imported?'local CSV, unvalidated':'seeded synthetic generator'} · ${person.readings.length} readings · ${person.meals.length} logged meals.</p></div></section><div class="evidence-grid" style="margin-top:20px"><section class="panel"><div class="panel-head"><h2>Latest readings at replay cursor</h2><span class="chip">CGM stream</span></div><div class="table-wrap"><table><thead><tr><th>Day</th><th>Time</th><th>Minute index</th><th>Glucose, mg/dL</th></tr></thead><tbody>${person.readings.slice(c-12,c+1).reverse().map(r=>`<tr><td>${Math.floor(r.minute/1440)+1}</td><td>${clock(r.minute)}</td><td>${r.minute}</td><td>${num(r.glucose,1)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="prose"><h3>Data contract</h3><p>Health record fields: age, fasting baseline, HbA1c, sleep hours and activity index. These inputs condition the synthetic model; they do not imply causal relationships.</p><h3>Temporal integrity</h3><p>At any replay cursor, the model reads only the preceding 60 minutes and meals already logged. Future readings exist solely to replay the fixture. They do not enter model features.</p><h3>Review threshold</h3><p>Illustrative crossing threshold, in mg/dL.</p><label>Threshold <input id="threshold" type="number" min="100" max="300" value="${threshold}"></label><h3>Explore missing data</h3><div class="data-actions">${button(withheld?'Restore readings':'Toggle missing reading','toggleMissing')}${button(stale?'Restore freshness':'Toggle stale sensor','toggleStale')}</div></div></section></div>`;}
function bindData(){$('#downloadCSV').onclick=()=>download('glyra-synthetic-series.csv','minute,glucose\n'+p().readings.map(r=>`${r.minute},${r.glucose}`).join('\n'),'text/csv');$('#restore').onclick=async()=>{people=await (await fetch('./data/fixtures.json')).json();withheld=stale=false;render();toast('Seeded synthetic fixtures restored.');};$('#import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>500000)throw new Error('Use a CSV smaller than 500 KB.');const readings=parseCSV(await file.text());p().readings=readings;p().cursor=readings.length-1;p().meals=[];p().imported=true;withheld=stale=false;render();toast('CSV loaded locally. Select Overview to inspect the forecast.');}catch(err){$('#importStatus').textContent=err.message;toast(err.message);}};$('#threshold').onchange=e=>{const v=Number(e.target.value);if(!Number.isFinite(v)||v<100||v>300){e.target.value=threshold;return toast('Choose a threshold from 100 to 300.');}threshold=v;toast('Illustrative review threshold updated.');};$('#toggleMissing').onclick=()=>{withheld=!withheld;toast(withheld?'Missing reading simulated. Forecast will be withheld.':'Readings restored.');render();};$('#toggleStale').onclick=()=>{stale=!stale;toast(stale?'Sensor is now stale. Forecast will be withheld.':'Freshness restored.');render();};}
$('#theme').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('glyra-theme',document.body.classList.contains('dark')?'dark':'light');};if(localStorage.getItem('glyra-theme')==='dark')document.body.classList.add('dark');
try{[model,benchmark,people]=await Promise.all(['model','benchmark','fixtures'].map(async f=>{const r=await fetch(`./data/${f}.json`);if(!r.ok)throw new Error('Cannot load model data.');return r.json();}));render();}catch(err){main.innerHTML='<div class="empty"><strong>Glyra could not load</strong><span>Serve the project with npm start, then reload this page.</span></div>';console.error(err);}
